"""Write repo-style H3 actions (50-120 words, "Starting from <Picture 1>, ...") into shots.json as h3_action.
Seedance / still shots keep their short "action". Run once: python scripts/h3_actions.py
"""
import json
from pathlib import Path

A = {
    "S02": "Starting from <Picture 1>, Ken stands on the sunny park path with his right hand already raised. He waves the hand from side to side three times, leans forward a little and greets his friend on the right with a big friendly smile, his eyebrows lifting on the word Allen. His spiky brown hair moves slightly in the breeze. After the line his lips close, he keeps smiling, lowers his hand to the strap of his orange backpack and waits for an answer, looking to the right.",
    "S03": "Starting from <Picture 1>, Allen stands on the park path in a relaxed pose with a small smile. He turns his face a little more toward the left, gives one calm nod and answers in a short, easy way. Leaves on the trees behind him sway gently in the breeze. After the line his lips close, he lifts his right hand to adjust the brim of his navy cap once, then lets the hand rest on the strap of his shoulder bag and keeps a gentle smile.",
    "S04": "Starting from <Picture 1>, Ken stands in the park with his eyes and head turned toward the right as if looking at someone beside his friend. He blinks twice, tilts his head slightly, raises his eyebrows with polite curiosity and asks his short question quietly. His mouth moves only while he speaks. After the line his lips close, he keeps looking to the right with curious, wide eyes and lifts one hand to scratch his cheek once, then lowers it.",
    "S05": "Starting from <Picture 1>, Allen stands on the left with his open right palm held toward Grandma on the right. He looks at the camera, smiles proudly and introduces her, moving the open palm slightly toward her on the word grandmother. Grandma stands still with her hands together in front of her and smiles warmly; her mouth stays closed. After the line Allen's lips close, he lowers his hand and turns his head to smile up at Grandma, and Grandma gives one gentle nod.",
    "S06": "Starting from <Picture 1>, Ken stands in the park facing the right. He straightens his back, gives a small polite bow of his head and greets Grandma brightly, his eyes curving into a happy smile. Both hands hold the straps of his orange backpack. After the line his lips close, he raises his head again, keeps smiling and gives one more small nod. Sunlight flickers through the leaves of the trees behind him.",
    "S07": "Starting from <Picture 1>, Grandma stands in the sunny park facing a little to the left. She smiles kindly, her eyes crinkling at the corners, and answers warmly in a gentle, unhurried way, giving a soft nod on the word too. A light breeze moves her short silver-gray hair. After the line her lips close into a warm smile, she lifts one hand to her chest for a moment, then lowers it and keeps looking kindly to the left.",
    "S08": "Starting from <Picture 1>, Ken stands on the left with his right arm stretched out and his open palm pointing toward the wooden bench on the right. He looks at Grandma, smiles politely and invites her to sit, moving his open palm slowly toward the bench on the word seat. Grandma stands still, turns her head to look at the bench and smiles; her mouth stays closed. After the line Ken's lips close, he keeps his arm pointing at the bench for a moment, then lowers it.",
    "S09": "Starting from <Picture 1>, Grandma sits on the wooden park bench with her hands on her knees. She settles back comfortably, looks toward the left with a grateful smile and thanks him gently, giving one soft nod. Sunlight and leaf shadows move across the bench. After the line her lips close, she smooths her trousers once with both hands and keeps smiling kindly to the left, relaxed on the bench.",
    "S10": "Starting from <Picture 1>, Ken stands in the park facing a little to the right. He smiles brightly and answers cheerfully, his eyes curving with happiness and his spiky hair bouncing as he gives a quick nod. Both hands hold the straps of his orange backpack. After the line his lips close into a wide smile, he rocks once onto his toes and back onto his heels and keeps looking happily to the right.",
    "S13": "Starting from <Picture 1>, Ken leans toward Allen in the foreground and asks his question quietly, as if telling a small secret, his curious eyes glancing once toward Grandma in the background. Allen listens and looks at Ken; his mouth stays closed. In the background Grandma keeps painting at her easel, moving her brush slowly across the canvas. After the line Ken's lips close, he straightens up a little and waits for the answer, still glancing at Grandma.",
    "S14": "Starting from <Picture 1>, Allen stands in the studio foreground facing a little to the left. He nods proudly and answers clearly with a confident smile, nodding again on the word is. Behind him Grandma, holding her brush at the easel, turns her head back and smiles; her mouth stays closed. After the line Allen's lips close, he puts both hands on the strap of his shoulder bag and keeps smiling proudly while Grandma turns back to her painting.",
    "S16": "Starting from <Picture 1>, Dad stands in the open studio doorway with one hand on the door frame, breathing a little fast. His shoulders rise and fall twice as he catches his breath. He lifts his free hand to scratch the back of his head, gives an apologetic smile and apologizes, bowing his head slightly on the word late. After the line his lips close, he lowers the hand and keeps an embarrassed smile, still holding the door frame.",
    "S17": "Starting from <Picture 1>, Grandma stands in the studio facing the door on the right with a warm smile. She shakes her head gently to show it is fine, then lifts her right hand and beckons him in twice with a friendly wave, speaking warmly and unhurriedly. After the line her lips close into a kind smile, she lowers the hand and steps half a step back to make room near the easels, still looking toward the door.",
    "S18": "Starting from <Picture 1>, Ken stands in the studio with his head turned toward the door on the right. His eyebrows lift with curiosity, he blinks once and asks his short question, leaning his head slightly toward the right. His mouth moves only while he speaks. After the line his lips close, he keeps looking toward the door with wide curious eyes and holds the straps of his orange backpack with both hands.",
    "S19": "Starting from <Picture 1>, Allen stands on the left with his open right palm held toward Dad on the right. He smiles happily and introduces him, moving the open palm slightly toward Dad on the word father. Dad smiles and waves his raised hand in greeting twice; his mouth stays closed. After the line Allen's lips close, he lowers his hand and looks up at Dad with a proud smile, and Dad lowers his hand and pats Allen's shoulder once.",
}

p = Path(__file__).resolve().parents[1] / "shots.json"
d = json.loads(p.read_text(encoding="utf-8"))
for s in d["shots"]:
    if s["id"] in A:
        s["h3_action"] = A[s["id"]]
p.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
for k, v in A.items():
    print(k, len(v.split()), "words")
